"""Composer metadata: the generated composers.yaml (from OpenScore data/composers.yaml) and composers-extra.yaml."""

from __future__ import annotations

import re
import unicodedata
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from .fetch import FetchError
from .paths import COMPOSERS_EXTRA_YAML, COMPOSERS_YAML
from .sources import Source
from .yamlio import dump_yaml, load_strict_strings, load_yaml

COMPOSERS_HEADER = (
    "Generated by `python -m corpus_build composers` from OpenScore data/composers.yaml at the pinned commits. Do not edit.\n"
    "Used by the public-domain gate (03 section 6.2). `died: null` means the source gives no death year, so the gate rejects.\n"
    "`paths` maps a corpus id to the composer's directory name under scores/."
)

_YEAR = re.compile(r"^\s*(\d{4})\s*$")


def norm_key(name: str) -> str:
    """Lower case, accents folded, every run of non-alphanumerics becomes one underscore."""
    s = unicodedata.normalize("NFKD", name)
    s = "".join(c for c in s if not unicodedata.combining(c))
    return re.sub(r"[^a-z0-9]+", "_", s.lower()).strip("_")


def parse_year(v: Any) -> int | None:
    if v is None:
        return None
    m = _YEAR.match(str(v))
    return int(m.group(1)) if m else None


def read_openscore_composers(src: Source, cache: Path) -> dict[str, dict[str, Any]]:
    """path (directory name) -> record, from the pinned clone's data/composers.yaml."""
    p = src.dir(cache) / (src.composer_metadata or "data/composers.yaml")
    if not p.is_file():
        raise FetchError(f"{src.id}: {p} is missing")
    raw = load_strict_strings(p) or {}
    out: dict[str, dict[str, Any]] = {}
    for wikidata_id, rec in raw.items():
        if not isinstance(rec, dict) or not rec.get("path"):
            continue
        out[rec["path"]] = {
            "name": rec.get("name") or rec["path"].replace("_", " "),
            "born": parse_year(rec.get("born")),
            "died": parse_year(rec.get("died")),
            "wikidata": rec.get("wikidata") or None,
            "imslp": rec.get("imslp") or None,
        }
    return out


def build_composers(sources: list[Source], cache: Path) -> dict[str, Any]:
    """Merge the OpenScore composer tables into one normalised table, keyed by `norm_key(name)`.

    If two sources disagree on the death year the later one is kept (conservative). If one gives none, the other is used."""
    merged: dict[str, dict[str, Any]] = {}
    for src in sources:
        if not src.composer_metadata or not (src.dir(cache) / ".git").exists():
            continue
        for path, rec in read_openscore_composers(src, cache).items():
            key = norm_key(rec["name"]) or norm_key(path)
            e = merged.setdefault(key, {"key": key, "name": rec["name"], "born": None, "died": None, "wikidata": None, "imslp": None, "paths": {}})
            e["paths"][src.id] = path
            for f in ("born", "wikidata", "imslp"):
                e[f] = e[f] or rec[f]
            if rec["died"] is not None:
                e["died"] = rec["died"] if e["died"] is None else max(e["died"], rec["died"])
    return {"version": 1, "composers": [merged[k] for k in sorted(merged)]}


def write_composers(data: dict[str, Any], path: Path = COMPOSERS_YAML) -> None:
    path.write_text(dump_yaml(data, COMPOSERS_HEADER), encoding="utf-8")


def load_composers(path: Path = COMPOSERS_YAML) -> dict[str, Any]:
    return load_yaml(path)


class ComposerIndex:
    """Lookup of generated composers by (corpus, directory name)."""

    def __init__(self, data: dict[str, Any]):
        self._by_path: dict[tuple[str, str], dict[str, Any]] = {}
        aliased: dict[tuple[str, str], dict[str, Any]] = {}
        for c in data["composers"]:
            for corpus, p in c["paths"].items():
                self._by_path[(corpus, p)] = c
                # OpenScore's metadata path can carry a suffix the score directory lacks:
                # "Hensel,_Fanny_(Mendelssohn)" and "Barnard,_Charlotte_Alington_-_aka_Claribel".
                short = re.sub(r"(_-_aka_.*|_\([^)]*\))$", "", p)
                if short != p:
                    aliased[(corpus, short)] = c
        for k, c in aliased.items():
            self._by_path.setdefault(k, c)

    def lookup(self, corpus: str, dirname: str) -> dict[str, Any] | None:
        return self._by_path.get((corpus, dirname))


@dataclass(frozen=True)
class Extra:
    key: str
    name: str
    born: int | None
    died: int | None
    references: tuple[str, ...]
    aliases: tuple[str, ...] = field(default=())


class ExtraIndex:
    def __init__(self, extras: list[Extra]):
        self.extras = extras
        self._by_alias: dict[str, Extra] = {}
        for e in extras:
            for a in (e.key, e.name, *e.aliases):
                self._by_alias[norm_key(a)] = e

    def lookup(self, name: str) -> Extra | None:
        return self._by_alias.get(norm_key(name))


def load_extras(path: Path = COMPOSERS_EXTRA_YAML) -> ExtraIndex:
    d = load_yaml(path) or {}
    items = []
    for c in d.get("composers") or []:
        items.append(
            Extra(
                key=c["key"], name=c["name"], born=c.get("born"), died=c.get("died"),
                references=tuple(c.get("references") or ()), aliases=tuple(c.get("aliases") or ()),
            )
        )
    return ExtraIndex(items)
